class Counter {
  private count = 0;
  constructor(private button: HTMLElement) {
    button.addEventListener('click', this.increment);
  }

  increment() {
    this.count += 1;
    this.render();
  }

  render() {
    this.button.textContent = String(this.count);
  }

  asCallback() {
    return this.increment;
  }
}
